import groovy.json.JsonOutput
import groovy.json.JsonSlurper

def prop = { name -> testRunner.testCase.testSuite.project.getPropertyValue(name) }

def payload = [akce: 'email-tip', from: 'test@example.com', subject: 'Testovaci tip', text: 'Testovaci akce v Testovacim meste, 1. 1. 2030.']
def bodyJson = JsonOutput.toJson(payload)

def conn = new URL(prop('baseUrl')).openConnection()
conn.setInstanceFollowRedirects(false)
conn.setRequestMethod('POST')
conn.setRequestProperty('Content-Type', 'application/json')
conn.setDoOutput(true)
conn.outputStream.withWriter('UTF-8') { it << bodyJson }

def status1 = conn.responseCode
assert status1 == 302 : "Apps Script /exec nevratil ocekavany 302 redirect (dostali jsme " + status1 + ") - endpoint se mozna zmenil"

def location = conn.getHeaderField('Location')
assert location : "302 odpoved neobsahuje Location header"

def getConn = new URL(location).openConnection()
getConn.setRequestMethod('GET')
def status2 = getConn.responseCode
def stream = (status2 in 200..299) ? getConn.inputStream : getConn.errorStream
def respText = stream.getText('UTF-8')
